import { initTRPC } from "@trpc/server";

/**
 * This is the context that is passed to the tRPC procedures.
 * It is created per-request by the `createContext` function in the
 * Next.js App Router API route.
 */
export interface Context {
  userId: string;
}

const t = initTRPC.context<Context>().create();

/**
 * The base tRPC router, pre-configured with our context type.
 */
export const router = t.router;
export const procedure = t.procedure;

import { router, procedure } from "./init";

/**
 * Application router.
 *
 * Currently exposes a single `getUser` procedure that returns the
 * `userId` extracted from the `x-user-id` request header (or
 * `'anonymous'` when the header is absent).
 */
export const appRouter = router({
  getUser: procedure.query(({ ctx }) => {
    return { userId: ctx.userId };
  }),
});

export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from "@trpc/server/adapters/fetch";
import { appRouter } from "@/trpc/router";
import type { Context } from "@/trpc/init";

/**
 * Create the tRPC context for a single request.
 *
 * `fetchRequestHandler` passes the standard Web `Request` object so we
 * can read headers directly from it.
 */
function createContext(req: Request): Context {
  const userId = req.headers.get("x-user-id") ?? "anonymous";
  return { userId };
}

/**
 * Next.js App Router route handler for tRPC.
 *
 * Every request to `/api/trpc/*` is forwarded to `fetchRequestHandler`
 * which dispatches it to the matching procedure on `appRouter`.
 */
function handler(req: Request) {
  return fetchRequestHandler({
    endpoint: "/api/trpc",
    req,
    router: appRouter,
    createContext: () => createContext(req),
  });
}

export { handler as GET, handler as POST };
